<?php declare(strict_types=1);require_once __DIR__.'/../../bootstrap/app.php';use App\Services\Auth;use App\Services\AuditService;Auth::requirePermission('ACCESS_LOG_VIEW');$rows=AuditService::access();$pageTitle='Access Logs';require BASE_PATH.'/app/Views/layout/header.php';?><div class="page-head"><div><h1>Access logs</h1><p>Recent authenticated portal requests.</p></div><span class="badge">Read only</span></div><div class="card table-wrap"><table><thead><tr><th>Time</th><th>User</th><th>Method</th><th>Path</th><th>IP</th><th>User agent</th></tr></thead><tbody><?php foreach($rows as$r):?><tr><td><?=h($r['occurred_at'])?></td><td><?=h($r['display_name']?:'Unknown')?></td><td><?=h($r['request_method'])?></td><td><?=h($r['request_path'])?></td><td><?=h($r['ip_address'])?></td><td><?=h($r['user_agent'])?></td></tr><?php endforeach;?></tbody></table></div><?php require BASE_PATH.'/app/Views/layout/footer.php';?>